import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { courseAPI, quizAPI } from '../api/api';
import { useAuth } from '../context/AuthContext';

export default function Dashboard() {
  const { user } = useAuth();
  const [enrollments, setEnrollments] = useState([]);
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      courseAPI.myEnrollments(),
      quizAPI.myResults(),
    ]).then(([eRes, qRes]) => {
      setEnrollments(eRes.data);
      setResults(qRes.data);
    }).finally(() => setLoading(false));
  }, []);

  const completed = enrollments.filter(e => e.status === 'COMPLETED').length;
  const avgScore = results.length
    ? Math.round(results.reduce((s, r) => s + r.percentage, 0) / results.length)
    : 0;

  if (loading) return <div style={styles.loading}>Loading dashboard...</div>;

  return (
    <div style={styles.page}>
      <h2 style={styles.heading}>Hello, {user?.fullName} 👋</h2>

      {/* Stats */}
      <div style={styles.statsRow}>
        {[
          { label: 'Enrolled Courses', value: enrollments.length, color: '#e94560' },
          { label: 'Completed', value: completed, color: '#16c79a' },
          { label: 'Quizzes Taken', value: results.length, color: '#f5a623' },
          { label: 'Avg Quiz Score', value: `${avgScore}%`, color: '#a29bfe' },
        ].map((s, i) => (
          <div key={i} style={{ ...styles.statCard, borderTop: `4px solid ${s.color}` }}>
            <div style={{ ...styles.statValue, color: s.color }}>{s.value}</div>
            <div style={styles.statLabel}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* My Courses */}
      <h3 style={styles.sectionTitle}>My Courses</h3>
      {enrollments.length === 0 ? (
        <div style={styles.empty}>
          No courses yet. <Link to="/courses" style={styles.link}>Browse courses →</Link>
        </div>
      ) : (
        <div style={styles.courseGrid}>
          {enrollments.map(e => (
            <div key={e.id} style={styles.courseCard}>
              <div style={styles.courseTitle}>{e.courseTitle}</div>
              <div style={styles.progressBar}>
                <div style={{ ...styles.progressFill, width: `${e.progressPercent}%` }} />
              </div>
              <div style={styles.progressLabel}>{e.progressPercent}% complete</div>
              <div style={{ ...styles.badge, background: e.status === 'COMPLETED' ? '#d4edda' : '#fff3cd' }}>
                {e.status === 'COMPLETED' ? '✅ Completed' : '📖 In Progress'}
              </div>
              <Link to={`/courses/${e.courseId}`} style={styles.viewBtn}>Continue →</Link>
            </div>
          ))}
        </div>
      )}

      {/* Quiz Results */}
      {results.length > 0 && (
        <>
          <h3 style={styles.sectionTitle}>Recent Quiz Results</h3>
          <div style={styles.table}>
            <div style={styles.tableHeader}>
              <span>Quiz</span><span>Score</span><span>Percentage</span>
            </div>
            {results.map(r => (
              <div key={r.resultId} style={styles.tableRow}>
                <span>{r.quizTitle}</span>
                <span>{r.score}/{r.total}</span>
                <span style={{ color: r.percentage >= 60 ? '#16c79a' : '#e94560', fontWeight:600 }}>
                  {r.percentage.toFixed(1)}%
                </span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

const styles = {
  page: { maxWidth:1100, margin:'0 auto', padding:'32px 24px' },
  heading: { color:'#1a1a2e', fontSize:28, marginBottom:24 },
  loading: { textAlign:'center', padding:60, color:'#888' },
  statsRow: { display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))', gap:16, marginBottom:36 },
  statCard: { background:'#fff', borderRadius:12, padding:'20px 24px', boxShadow:'0 2px 12px rgba(0,0,0,0.07)' },
  statValue: { fontSize:32, fontWeight:700 },
  statLabel: { color:'#888', fontSize:13, marginTop:4 },
  sectionTitle: { color:'#1a1a2e', fontSize:20, marginBottom:16 },
  empty: { color:'#888', padding:'20px 0' },
  link: { color:'#e94560', textDecoration:'none' },
  courseGrid: { display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))', gap:16, marginBottom:36 },
  courseCard: { background:'#fff', borderRadius:12, padding:20, boxShadow:'0 2px 12px rgba(0,0,0,0.07)' },
  courseTitle: { fontWeight:600, color:'#1a1a2e', marginBottom:12, fontSize:15 },
  progressBar: { background:'#eee', borderRadius:20, height:8, marginBottom:6 },
  progressFill: { background:'#e94560', height:8, borderRadius:20, transition:'width 0.3s' },
  progressLabel: { fontSize:12, color:'#888', marginBottom:10 },
  badge: { display:'inline-block', padding:'3px 10px', borderRadius:20, fontSize:12, marginBottom:12 },
  viewBtn: { display:'block', textAlign:'center', padding:'8px 0', background:'#e94560', color:'#fff', borderRadius:8, textDecoration:'none', fontSize:13 },
  table: { background:'#fff', borderRadius:12, overflow:'hidden', boxShadow:'0 2px 12px rgba(0,0,0,0.07)' },
  tableHeader: { display:'grid', gridTemplateColumns:'1fr auto auto', gap:16, padding:'12px 20px', background:'#f8f9fa', fontWeight:600, color:'#555', fontSize:13 },
  tableRow: { display:'grid', gridTemplateColumns:'1fr auto auto', gap:16, padding:'12px 20px', borderTop:'1px solid #f0f0f0', fontSize:14 },
};
